  assert.deepEqual(await page.$$eval('[data-motion-stream="direction"] option',ns=>ns.map(n=>n.value)),['horizontal','vertical']);assert.deepEqual(await page.$$eval('[data-motion-stream="focusMode"] option',ns=>ns.map(n=>n.value)),['start','center']);assert.deepEqual(await page.$$eval('[data-motion-stream="movement"] option',ns=>ns.map(n=>n.value)),['smooth','stepped']);assert.equal(await page.$eval('[data-motion-stream="fade"]',n=>n.checked),false);for(const key of ['motion','tilt','globeSize','cardSize','focusZoom','focusStyle','stops','offsetX','offsetY'])assert.equal(await page.$('[data-motion-stream="'+key+'"]'),null);
  const start=await pose(.5);assert.ok(start.some(n=>n.instances.length));assert.deepEqual(geometry(await pose(0)),geometry(await pose(1)));await pose(.16);await(await page.$('.nw-motion-dialog')).screenshot({path:'/tmp/nagweb-motion-visuals/'+template+'-desktop.png'});
