  let pixelCount=0,fadeCopies=false;for(const frameRatio of ['16:9','9:16']){await change('[data-motion-stream="frameRatio"]',frameRatio);for(const direction of ['horizontal','vertical']){await change('[data-motion-stream="direction"]',direction);for(const focusMode of ['start','center']){await change('[data-motion-stream="focusMode"]',focusMode);await change('[data-motion-stream="movement"]',focusMode==='center'?'stepped':'smooth');for(const fade of [false,true]){await change('[data-motion-stream="fade"]',fade);assert.deepEqual(geometry(await pose(0)),geometry(await pose(1)));for(const alpha of [1,.5]){await colors(alpha);for(const progress of [0,.16,.51,.9]){const points=await samples(progress,8);assert.ok(points.length>0,'Visible grid strip '+JSON.stringify({frameRatio,direction,focusMode,fade,progress}));for(const [i,point] of points.entries()){checkPixel(point,alpha,{frameRatio,direction,focusMode,fade,progress});pixelCount++;if(alpha===1&&i<1)await clickPoint(point.x,point.y,point.id);}}}if(fade)fadeCopies||=(await pose(.16)).some(n=>n.instances.length===2);}}}}
  assert.ok(fadeCopies,'Grid/strip copies are independently composited');await change('[data-motion-stream="frameRatio"]','16:9');await change('[data-motion-stream="direction"]','horizontal');await change('[data-motion-stream="focusMode"]','start');await change('[data-motion-stream="movement"]','smooth');await change('[data-motion-stream="fade"]',true);for(const alpha of [1,.5]){await colors(alpha);const points=await samples(.16,140,true);assert.ok(points.length>=100,'Enough transition interior samples: '+points.length);for(const point of points){checkPixel(point,alpha,'Fade planes preserve source alpha once per copy');pixelCount++;}}assert.ok(pixelCount>500);await change('[data-motion-stream="fade"]',false);
  await colors();await pose(0);const gap=await page.$eval('.nw-motion-dialog iframe',f=>{const d=f.contentDocument,m=window.NAGWEB_STREAM_MODEL,ns=Array.from(d.querySelectorAll('[data-nw-stream-slot]')),clip=ns[0].__nwMotionClip,tiles=ns.flatMap(n=>n.__nwMotionInstances);for(const t of tiles){const p={x:t.upper[1].x+6,y:t.center.y};if(p.x>clip.left+8&&p.x<clip.left+clip.width-8&&p.y>clip.top+8&&p.y<clip.top+clip.height-8&&!tiles.some(z=>m.meshUV(z.mesh,p.x,p.y)))return p;}return null;});assert.ok(gap,'Empty gap between grid images');const blank=await at(gap.x,gap.y);assert.equal(blank[3],0);await clickPoint(gap.x,gap.y,null);
  await change('[data-motion-stream="shadow"]',true);await colors();await pose(0);assert.ok((await at(gap.x,gap.y))[3]>blank[3]+1,'Optional shadow paints beyond card');await clickPoint(gap.x,gap.y,null);await change('[data-motion-stream="shadow"]',false);
  await change('[data-motion-stream="cornerRadius"]','12');await colors();await pose(0);const corner=await page.$eval('.nw-motion-dialog iframe',f=>{const d=f.contentDocument,m=window.NAGWEB_STREAM_MODEL,ns=Array.from(d.querySelectorAll('[data-nw-stream-slot]')),clip=ns[0].__nwMotionClip,tiles=ns.flatMap(n=>n.__nwMotionInstances);for(const t of tiles)for(const [u,v] of [[.005,.005],[.995,.005],[.005,.995],[.995,.995]]){const p=m.meshPoint(t.mesh,u,v);if(!p||p.x<clip.left+8||p.x>clip.left+clip.width-8||p.y<clip.top+8||p.y>clip.top+clip.height-8)continue;if(!tiles.some(z=>m.meshUV(z.mesh,p.x,p.y)))return p;}return null;});assert.ok(corner,'Empty rounded grid corner');assert.ok((await at(corner.x,corner.y))[3]<8);await clickPoint(corner.x,corner.y,null);
