  const reuse=await page.$eval('.nw-motion-dialog iframe',f=>{const d=f.contentDocument,clock=f.contentWindow.__NAG_SCROLL_DIRECTOR[d.querySelector('.sc').dataset.id];for(let i=0;i<20;i++)clock.set(i/20);const native=d.createElement;let created=0;d.createElement=function(...a){if(a[0]==='canvas')created++;return native.apply(this,a);};try{for(let i=0;i<20;i++)clock.set(i/20);return{created,bounded:Array.from(d.querySelectorAll('canvas')).every(c=>c.width<=2048&&c.height<=2048)};}finally{d.createElement=native;}});assert.equal(reuse.created,0);assert.equal(reuse.bounded,true);console.log('Grid Zoom Strip pixels: grid/strip/morph fade compositing, both directions and initial focus modes, smooth/stepped travel, opaque/semitransparent source alpha, native picking, empty gaps/optional shadows, constant screen corners and zero warmed canvas allocations OK');
